import { defineEntity, p } from "@mikro-orm/postgresql";
import { baseProperties } from "../base.entity";

export const UserSchema = defineEntity({
  name: "User",
  tableName: "users",
  properties: {
    ...baseProperties(),
    email: p.string().length(320).unique(),
    name: p.string().nullable(),
  },
});

// Use the class generated by `defineEntity` (named from `name`), not a subclass:
// minification renames subclasses per bundle, and Next bundles pages and route
// handlers separately, which breaks MikroORM's metadata lookup by class name.
export const User = UserSchema.class;
export type User = InstanceType<typeof User>;
